ALTER TABLE tasks ADD COLUMN priority INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS task_blockers (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, author_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at INTEGER NOT NULL, resolved_at INTEGER, resolved_by INTEGER);
CREATE INDEX IF NOT EXISTS idx_blockers_task ON task_blockers(task_id, resolved_at);
